void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class T>T* child(FinancialModelPane& pane,const char* name){auto* value=pane.findChild<T*>(name);require(value,"Expected accessible pane control");return value;}
void lifecycle(){FinancialModelPane pane;int stopped=0,accepted=0,discarded=0;pane.cancelRequested=[&]{++stopped;};pane.acceptRequested=[&]{++accepted;};pane.discardRequested=[&]{++discarded;};pane.setRunState("running","Evaluating scenario 2 of 5");auto* status=child<QLabel>(pane,"financial.status");require(status->text().contains("scenario 2"),"Running status explains active work");require(!status->accessibleName().isEmpty(),"Status has accessible name");auto* stop=child<QPushButton>(pane,"financial.cancel");require(stop->isEnabled()&&!stop->isHidden(),"Running job exposes Stop");require(!child<QPushButton>(pane,"financial.run")->isEnabled(),"Running job cannot start competing work");require(child<QProgressBar>(pane,"financial.progress")->maximum()==0,"Unknown duration displays indeterminate progress");stop->click();require(stopped==1,"Stop dispatches cancellation callback");pane.setRunState("preview","Preview changes three assumption cells",true);require(child<QPushButton>(pane,"financial.accept")->isEnabled(),"Qualified preview enables Accept");child<QPushButton>(pane,"financial.accept")->click();child<QPushButton>(pane,"financial.discard")->click();require(accepted==1&&discarded==1,"Review exposes explicit accept/discard callbacks");pane.setRunState("error","The target output is not numeric");require(status->text().contains("not numeric"),"Failure retains actionable diagnostic");require(!child<QPushButton>(pane,"financial.accept")->isEnabled(),"Failure cannot accept stale results");require(child<QPushButton>(pane,"financial.run")->isEnabled(),"Failure allows corrected retry");}
void forecast(){FinancialModelPane pane;const Json sheets=Json::array({{{"id","inputs"},{"name","Assumptions"}},{{"id","report"},{"name","Forecast"}}});pane.setWorkbookContext(sheets,"inputs",{{"sheet","inputs"},{"row",2},{"col",2}});const Json original={{"id","revenue"},{"version",1},{"name","Revenue forecast"},{"kind","forecast"},{"periods",5},{"startPeriod",2027},{"drivers",Json::array({{{"name","Revenue"},{"base",{{"sheet","inputs"},{"row",2},{"col",2}}},{"growth",0.1},{"numberFormat","$#,##0.00"}}})},{"output",{{"sheet","report"},{"row1",1},{"col1",1}}}};pane.setDefinition(original);require(pane.definition()==original,"Saved forecast definition roundtrips without source cell copies");auto* drivers=child<QTableWidget>(pane,"forecast.drivers");require(drivers->rowCount()==1&&drivers->item(0,1)->text().contains("B2"),"Driver editor shows bound base cell");drivers->item(0,2)->setText("12.5%");child<QSpinBox>(pane,"forecast.periods")->setValue(8);Json saved,ran;pane.saveRequested=[&](const Json& value){saved=value;};pane.runRequested=[&](const Json& value){ran=value;};require(child<QPushButton>(pane,"financial.save")->text()=="Save and preview","Generated report configuration saves only through reviewed result");require(child<QPushButton>(pane,"financial.save")->accessibleDescription().contains("Accept"),"Report save explains acceptance requirement");child<QPushButton>(pane,"financial.save")->click();require(saved.is_null()&&ran.at("periods")==8&&ran.at("drivers")[0].at("growth")==0.125,"Report save validates and previews rather than claiming unsaved metadata");const auto expected=ran;child<QPushButton>(pane,"financial.run")->click();require(ran==expected,"Preview dispatches configuration without synchronous calculation");drivers->item(0,2)->setText("not a number or reference");ran=nullptr;child<QPushButton>(pane,"financial.run")->click();require(ran.is_null()&&child<QLabel>(pane,"financial.status")->text().contains("growth",Qt::CaseInsensitive),"Invalid driver refuses dispatch with field diagnostic");}
void typedScenario(){FinancialModelPane pane;pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Inputs"}}}),"s");const Json original={{"id","up"},{"version",1},{"name","Upside"},{"kind","scenario"},{"cells",Json::array({{{"sheet","s"},{"row",2},{"col",1},{"type","number"},{"value",0.15}},{{"sheet","s"},{"row",3},{"col",1},{"type","string"},{"value","00123"}},{{"sheet","s"},{"row",4},{"col",1},{"type","boolean"},{"value",true}},{{"sheet","s"},{"row",5},{"col",1},{"type","blank"},{"value",nullptr}}})}};pane.setDefinition(original);require(pane.definition()==original,"Saved scenario retains typed assumptions including leading-zero text and blank");auto* cells=child<QTableWidget>(pane,"financial.assumptionCells");cells->item(1,2)->setText("=AVERAGE(A1:A2)");Json saved;pane.saveRequested=[&](const Json& value){saved=value;};child<QPushButton>(pane,"financial.save")->click();require(saved.at("cells")[1].at("type")=="string"&&saved.at("cells")[1].at("value")=="=AVERAGE(A1:A2)","Scenario formula-looking text remains literal text");cells->item(1,0)->setText("A2");saved=nullptr;child<QPushButton>(pane,"financial.save")->click();require(saved.is_null()&&child<QLabel>(pane,"financial.status")->text().contains("unique",Qt::CaseInsensitive),"Duplicate assumption target refuses save");}
void contextKeepsDraft(){FinancialModelPane pane;const Json sheets=Json::array({{{"id","s"},{"name","Inputs"}},{{"id","r"},{"name","Report"}}});const Json value={{"id","f"},{"version",1},{"name","Saved"},{"kind","forecast"},{"periods",3},{"startPeriod",2027},{"drivers",Json::array({{{"name","Revenue"},{"base",100},{"growth",0.1},{"numberFormat","0.00"}}})},{"output",{{"sheet","r"},{"row1",4},{"col1",2}}}};pane.setWorkbookContext(sheets,"s",Json::object(),Json::array({value}));pane.setDefinition(value);child<QLineEdit>(pane,"financial.name")->setText("Unsaved draft");pane.setWorkbookContext(sheets,"s",{{"sheet","s"},{"row",2},{"col",2}},Json::array({value}));require(pane.definition().at("name")=="Unsaved draft"&&pane.definition().at("output")==value.at("output"),"Context/status refresh preserves edited setup and report destination");}
void savedSetups(){FinancialModelPane pane;Json first={{"id","base"},{"version",1},{"name","Base"},{"kind","scenario"},{"cells",Json::array({{{"sheet","s"},{"row",2},{"col",1},{"type","number"},{"value",100}}})}};auto second=first;second["id"]="up";second["name"]="Upside";second["cells"][0]["value"]=120;pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Inputs"}}}),"s",{{"sheet","s"},{"row",2},{"col",1}},Json::array({first,second}));auto* saved=child<QComboBox>(pane,"financial.saved");saved->setCurrentIndex(saved->findData("up"));require(pane.definition()==second,"Saved setup selection reloads exact editable definition");std::string removed;pane.deleteRequested=[&](const std::string& id){removed=id;};child<QPushButton>(pane,"financial.delete")->click();require(removed=="up","Delete dispatches selected saved setup id for host preview");child<QPushButton>(pane,"financial.new")->click();const auto created=pane.definition();require(created.at("id")!="up"&&created.at("kind")=="scenario","New setup creates independent id without overwriting saved configuration");saved->setCurrentIndex(saved->findData("up"));saved->setCurrentIndex(0);require(pane.definition().at("id")!="up","Choosing New setup in the picker cannot overwrite the previously selected saved setup");}
void comparison(){FinancialModelPane pane;const Json sets=Json::array({{{"id","base"},{"name","Base"},{"kind","assumption_set"},{"version",1},{"cells",Json::array()}},{{"id","up"},{"name","Upside"},{"kind","scenario"},{"version",1},{"cells",Json::array()}}});pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Model"}},{{"id","r"},{"name","Report"}}}),"s",Json::object(),sets);const Json original={{"id","cmp"},{"version",1},{"name","Scenario comparison"},{"kind","scenario_comparison"},{"scenarioIds",Json::array({"up","base"})},{"includeBaseline",false},{"outputs",Json::array({{{"sheet","s"},{"row",8},{"col",2},{"label","Profit"}}})},{"output",{{"sheet","r"},{"row1",1},{"col1",1}}}};pane.setDefinition(original);require(pane.definition()==original,"Comparison roundtrips ordered scenario membership, outputs and absent format");auto* scenarios=child<QListWidget>(pane,"comparison.scenarios");require(scenarios->count()==2&&scenarios->item(0)->data(Qt::UserRole)=="up","Comparison preserves selected report scenario order");scenarios->item(1)->setCheckState(Qt::Unchecked);child<QCheckBox>(pane,"comparison.includeBaseline")->setChecked(true);Json run;pane.runRequested=[&](const Json& value){run=value;};child<QPushButton>(pane,"financial.run")->click();require(run.at("scenarioIds")==Json::array({"up"})&&run.at("includeBaseline")==true,"Comparison emits edited membership and baseline option for isolated preview");}
void sensitivity(){FinancialModelPane pane;pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Model"}},{{"id","r"},{"name","Report"}}}),"s");const Json original={{"id","sens"},{"version",1},{"name","Revenue sensitivity"},{"kind","sensitivity"},{"inputs",Json::array({{{"sheet","s"},{"row",2},{"col",2},{"values",Json::array({0.05,0.1})}},{{"sheet","s"},{"row",3},{"col",2},{"values",Json::array({10,20,30})}}})},{"result",{{"sheet","s"},{"row",8},{"col",2},{"label","NPV"},{"numberFormat","$#,##0.00"}}},{"output",{{"sheet","r"},{"row1",1},{"col1",1}}}};pane.setDefinition(original);require(pane.definition()==original,"Two-variable sensitivity roundtrips explicit axes and result format");auto* inputs=child<QTableWidget>(pane,"sensitivity.inputs");inputs->item(0,1)->setText("5%, 12.5%");child<QComboBox>(pane,"sensitivity.dimensions")->setCurrentIndex(0);const auto one=pane.definition();require(one.at("inputs").size()==1&&one.at("inputs")[0].at("values")==Json::array({0.05,0.125}),"One-variable editor emits explicit finite percentage values");Json run;pane.runRequested=[&](const Json& value){run=value;};inputs->item(0,1)->setText("1, nan");child<QPushButton>(pane,"financial.run")->click();require(run.is_null()&&child<QLabel>(pane,"financial.status")->text().contains("finite",Qt::CaseInsensitive),"Nonfinite sensitivity values block isolated worker dispatch");}
void goalSeek(){FinancialModelPane pane;pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Model"}}}),"s");const Json original={{"id","goal"},{"version",1},{"name","Target profit"},{"kind","goal_seek"},{"specification",{{"output",{{"sheet","s"},{"row",8},{"col",2}}},{"changing",{{"sheet","s"},{"row",2},{"col",2}}},{"target",1000},{"start",10},{"lower",0},{"upper",100},{"tolerance",1e-9},{"relativeTolerance",0},{"maxIterations",100},{"maxEvaluations",200}}}};pane.setDefinition(original);require(pane.definition()==original,"Goal Seek saved setup roundtrips target, start, bounds and convergence limits");child<QLineEdit>(pane,"goal.target")->setText("1200");Json saved,run;pane.saveRequested=[&](const Json& value){saved=value;};pane.runRequested=[&](const Json& value){run=value;};child<QPushButton>(pane,"financial.save")->click();require(saved.at("specification").at("target")==1200&&run.is_null(),"Saving Goal Seek setup does not run a solve");child<QLineEdit>(pane,"goal.lower")->setText("101");child<QPushButton>(pane,"financial.run")->click();require(run.is_null()&&child<QLabel>(pane,"financial.status")->text().contains("bound",Qt::CaseInsensitive),"Reversed Goal Seek bounds refuse numerical dispatch");}
void solver(){FinancialModelPane pane;pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Model"}}}),"s");const Json original={{"id","solve"},{"version",1},{"name","Maximize profit"},{"kind","solver"},{"specification",{{"objective",{{"sheet","s"},{"row",8},{"col",2}}},{"goal","max"},{"method","linear"},{"variables",Json::array({{{"sheet","s"},{"row",2},{"col",2},{"lower",0},{"upper",100},{"start",10},{"integer",false},{"binary",false}}})},{"constraints",Json::array({{{"sheet","s"},{"row",9},{"col",2},{"relation","<="},{"value",500}}})},{"tolerance",1e-7},{"maxEvaluations",10000},{"seed",42}}}};pane.setDefinition(original);require(pane.definition()==original,"Solver setup roundtrips objective, bounds, starts, constraints and reproducibility options");auto* variables=child<QTableWidget>(pane,"solver.variables");variables->item(0,3)->setText("10.5");static_cast<QComboBox*>(variables->cellWidget(0,4))->setCurrentIndex(1);Json run;pane.runRequested=[&](const Json& value){run=value;};child<QPushButton>(pane,"financial.run")->click();require(run.is_null()&&child<QLabel>(pane,"financial.status")->text().contains("integer",Qt::CaseInsensitive),"Fractional explicit integer start refuses dispatch");variables->item(0,3)->setText("11");child<QPushButton>(pane,"financial.run")->click();require(run.at("specification").at("variables")[0].at("integer")==true&&run.at("specification").at("variables")[0].at("start")==11,"Solver emits valid edited start/type for isolated preview");}
void defaults(){FinancialModelPane pane;const Json selection={{"sheet","s"},{"row",8},{"col",2},{"type","number"},{"value",150}};const Json cases=Json::array({{{"id","base"},{"version",1},{"name","Base"},{"kind","scenario"},{"cells",Json::array({{{"sheet","s"},{"row",2},{"col",1},{"type","number"},{"value",10}}})}}});pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Model"}}}),"s",selection,cases);std::set<std::string> ids;for(const auto* kind:{"forecast","assumption_set","scenario","scenario_comparison","sensitivity","goal_seek","solver"}){const auto value=defaultFinancialDefinition(kind,"s",selection,cases);require(value.at("kind")==kind&&!value.at("name").get<std::string>().empty()&&ids.insert(value.at("id").get<std::string>()).second,"Every financial workflow has a distinct named draft");pane.setDefinition(value);require(pane.definition().at("kind")==kind,"Default draft loads into every native configuration editor");}bool rejected=false;try{defaultFinancialDefinition("unknown","s");}catch(const std::exception&){rejected=true;}require(rejected,"Unknown financial workflow refuses a fake default");}
void cachedConsent(){FinancialModelPane pane;require(!pane.allowCachedLinks(),"Saved linked-source consent defaults off");auto* consent=child<QCheckBox>(pane,"financial.allowCachedLinks");require(consent->accessibleName().contains("saved",Qt::CaseInsensitive)&&consent->accessibleDescription().contains("unavailable",Qt::CaseInsensitive),"Consent plainly identifies saved and unavailable linked sources");consent->setChecked(true);require(pane.allowCachedLinks(),"Explicit checked consent is available to the isolated host request");pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Model"}}}),"s");pane.setDefinition(defaultFinancialDefinition("scenario","s"));require(!pane.definition().contains("allowCachedLinks"),"Consent is not persisted with a saved financial setup");pane.setRunState("running");require(!consent->isEnabled(),"A running job cannot change its captured source grant");pane.resetCachedLinkConsent();require(!pane.allowCachedLinks(),"Host can clear the grant on workbook/context replacement");}
void iteration(){FinancialModelPane pane;const Json settings={{"iterationEnabled",false},{"maxIterations",100},{"maxChange",0.001},{"showGrid",true}};pane.setIterationSettings(settings);auto* enabled=child<QCheckBox>(pane,"iteration.enabled");enabled->setChecked(true);child<QLineEdit>(pane,"iteration.maxChange")->setText("0");pane.setIterationSettings(settings);require(child<QLineEdit>(pane,"iteration.maxChange")->text()=="0","Repeated context refresh preserves the iteration draft");Json reviewed;int examples=0;pane.settingsRequested=[&](const Json& value){reviewed=value;};pane.exampleRequested=[&]{++examples;};child<QPushButton>(pane,"iteration.apply")->click();require(reviewed.at("iterationEnabled")==true&&reviewed.at("maxChange")==0&&reviewed.at("showGrid")==true,"Iteration review delegates settings with unrelated values preserved");child<QPushButton>(pane,"iteration.example")->click();require(examples==1,"Circular financing example dispatches a reviewed host request");pane.setRunState("running");require(!child<QPushButton>(pane,"iteration.apply")->isEnabled(),"Iteration cannot change captured calculation context during a run");}
void optionalMetadata(){FinancialModelPane pane;const Json cases=Json::array({{{"id","up"},{"version",1},{"name","Upside"},{"kind","scenario"},{"cells",Json::array({{{"sheet","s"},{"row",2},{"col",1},{"type","number"},{"value",120}}})}}});pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Model"}}}),"s",Json::object(),cases);auto forecast=defaultFinancialDefinition("forecast","s");forecast["assumptionSetId"]="up";forecast["drivers"][0].erase("numberFormat");pane.setDefinition(forecast);require(pane.definition()==forecast,"Forecast preserves scenario binding and an omitted General number format");auto sensitivity=defaultFinancialDefinition("sensitivity","s");sensitivity["inputs"][0]["numberFormat"]="0.0%";pane.setDefinition(sensitivity);require(pane.definition()==sensitivity,"Sensitivity preserves saved input-axis number format");}
void keyboard(){FinancialModelPane pane;pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Model"}}}),"s");pane.setDefinition(defaultFinancialDefinition("forecast","s"));int runs=0,stops=0,accepted=0;pane.runRequested=[&](const Json&){++runs;};pane.cancelRequested=[&]{++stops;};pane.acceptRequested=[&]{++accepted;};pane.resize(680,900);pane.show();require(QTest::qWaitForWindowExposed(&pane),"Financial pane exposes for keyboard input");pane.activateWindow();auto* name=child<QLineEdit>(pane,"financial.name");name->setFocus();QCoreApplication::processEvents();QTest::keyClick(name,Qt::Key_Return,Qt::ControlModifier);require(runs==1,"Ctrl+Enter previews the focused financial setup");pane.setRunState("running");auto* stop=child<QPushButton>(pane,"financial.cancel");stop->setFocus();QTest::keyClick(stop,Qt::Key_Space);require(stops==1,"Stop is keyboard operable");pane.setRunState("preview","Review the candidate",true);auto* accept=child<QPushButton>(pane,"financial.accept");accept->setFocus();QTest::keyClick(accept,Qt::Key_Space);require(accepted==1,"Accept preview is keyboard operable");QTest::keyClick(accept,Qt::Key_Tab);require(QApplication::focusWidget()==child<QPushButton>(pane,"financial.discard"),"Tab reaches the adjacent explicit Discard action");}
void nameBound(){FinancialModelPane pane;pane.setWorkbookContext(Json::array({{{"id","s"},{"name","Model"}}}),"s");pane.setDefinition(defaultFinancialDefinition("scenario","s"));child<QLineEdit>(pane,"financial.name")->setText(QString(65,'x'));bool saved=false;pane.saveRequested=[&](const Json&){saved=true;};child<QPushButton>(pane,"financial.save")->click();require(!saved&&child<QLabel>(pane,"financial.status")->text().contains("64"),"Financial name limit matches the persisted 64-character contract before dispatch");}
void staleStatus(){FinancialModelPane pane;const Json sheets=Json::array({{{"id","s"},{"name","Model"}}});auto report=defaultFinancialDefinition("forecast","s");report["stale"]=true;report["cache"]={{"records",Json::array({1,2,3})}};report["assumptions"]=Json::array({{{"generated",true}}});pane.setWorkbookContext(sheets,"s",Json::object(),Json::array({report}));auto* picker=child<QComboBox>(pane,"financial.saved");picker->setCurrentIndex(picker->findData(QString::fromStdString(report.at("id").get<std::string>())));require(picker->currentText().contains("Stale")&&child<QLabel>(pane,"financial.status")->text().contains("Stale"),"Saved stale reports show freshness in the picker and selected report status");const auto editable=pane.definition();require(!editable.contains("stale")&&!editable.contains("cache")&&!editable.contains("assumptions"),"Editable report definitions exclude freshness and generated source caches");child<QLineEdit>(pane,"financial.name")->setText("Unsaved draft");pane.setRunState("running","Computing the draft");report["stale"]=false;pane.setWorkbookContext(sheets,"s",Json::object(),Json::array({report}));require(pane.definition().at("name")=="Unsaved draft"&&!picker->currentText().contains("Stale")&&child<QLabel>(pane,"financial.status")->text().contains("Computing the draft"),"Freshness updates preserve authoring and running status");pane.setRunState("preview","Review candidate",true);report["stale"]=true;pane.setWorkbookContext(sheets,"s",Json::object(),Json::array({report}));require(child<QLabel>(pane,"financial.status")->text().contains("Review candidate")&&child<QPushButton>(pane,"financial.accept")->isEnabled(),"Freshness updates retain qualified preview controls");pane.setRunState("idle");require(child<QLabel>(pane,"financial.status")->text().contains("Stale")&&child<QLabel>(pane,"financial.status")->text().contains("Preview",Qt::CaseInsensitive),"Idle stale report explains the refresh preview action");report["stale"]=false;pane.setWorkbookContext(sheets,"s",Json::object(),Json::array({report}));require(!child<QLabel>(pane,"financial.status")->text().contains("Stale"),"Current context clears the stale status without replacing the draft");}

