int main(int argc,char**argv){QApplication app(argc,argv);try{lifecycle();forecast();typedScenario();contextKeepsDraft();savedSetups();comparison();sensitivity();goalSeek();solver();defaults();cachedConsent();iteration();optionalMetadata();keyboard();nameBound();staleStatus();std::cout<<"financial pane tests passed\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
